    cublasOperation_t trans_b = CUBLAS_OP_T;
    cublasLtMatmulDescSetAttribute(matmul_desc, CUBLASLT_MATMUL_DESC_TRANSA, &trans_a, sizeof(trans_a));
    cublasLtMatmulDescSetAttribute(matmul_desc, CUBLASLT_MATMUL_DESC_TRANSB, &trans_b, sizeof(trans_b));

    cublasLtEpilogue_t epilogue = CUBLASLT_EPILOGUE_BIAS;
    cublasLtMatmulDescSetAttribute(matmul_desc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epilogue, sizeof(epilogue));
    cublasLtMatmulDescSetAttribute(matmul_desc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &(bias.data_ptr<float>()), sizeof(float*));

    cublasLtMatrixLayoutCreate(&x_desc, CUDA_R_32F, M, K, K);
    cublasLtMatrixLayoutCreate(&weight_desc, CUDA_R_32F, N, K, K);
    cublasLtMatrixLayoutCreate(&out_desc, CUDA_R_32F, M, N, N);

    cublasLtMatmulPreference_t preference;
    cublasLtMatmulPreferenceCreate(&preference);
    cublasLtMatmulPreferenceSetAttribute(preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &g_workspace_size, sizeof(g_workspace_size));

